"gyrokinetic/zero/gkyl_gk_fluid_moments.h":`#pragma once

#include <gkyl_array.h>
#include <gkyl_basis.h>
#include <gkyl_mom_type.h>
#include <gkyl_range.h>
#include <gkyl_rect_grid.h>

struct gkyl_gk_fluid_moments;

// Analytic Maxwellian/bi-Maxwellian moments of the configuration-space state
// (J*n, upar, Tpar/m, Tperp/m). The perpendicular component is ignored for vdim=1.
// Integrated outputs contain cell integrals; other outputs contain DG coefficients.
struct gkyl_gk_fluid_moments *gkyl_gk_fluid_moments_new(
  const struct gkyl_basis *basis, const struct gkyl_rect_grid *grid, int vdim,
  double mass, double charge, enum gkyl_distribution_moments moment,
  bool integrated, bool use_gpu);

int gkyl_gk_fluid_moments_num_mom(const struct gkyl_gk_fluid_moments *up);

void gkyl_gk_fluid_moments_advance(const struct gkyl_gk_fluid_moments *up,
  const struct gkyl_range *range, const struct gkyl_array *state,
  const struct gkyl_array *phi, struct gkyl_array *out);

void gkyl_gk_fluid_moments_release(struct gkyl_gk_fluid_moments *up);
`,
"gyrokinetic/zero/gkyl_gk_fluid_moments_priv.h":`#pragma once

#include <gkyl_gk_fluid_moments.h>

struct gkyl_gk_fluid_moments {
  int num_basis, num_quad, num_mom, vdim;
  double mass, charge, cell_factor;
  enum gkyl_distribution_moments moment;
  bool integrated, use_gpu;
  struct gkyl_array *quad; // Basis values followed by quadrature weight at each node.
};

// Shared CPU/CUDA evaluation: exact configuration-space quadrature for the
// polynomial Maxwellian closure, including products before projection.
GKYL_CU_DH static inline void
gk_fluid_moments_cell(const struct gkyl_gk_fluid_moments *up,
  const double *state, const double *phi, const struct gkyl_array *quad, double *out)
{
  int nb = up->num_basis, nout = up->integrated ? 1 : nb;
  for (int k = 0; k < up->num_mom*nout; ++k) out[k] = 0.0;
  for (int q = 0; q < up->num_quad; ++q) {
    const double *b = (const double *) gkyl_array_cfetch(quad, q);
    double val[4] = {0.0}, potential = 0.0;
    for (int k = 0; k < nb; ++k) {
      for (int c = 0; c < 4; ++c) val[c] += state[c*nb+k]*b[k];
      if (phi) potential += phi[k]*b[k];
    }
    double dens = val[0], upar = val[1], tpar = val[2];
    double tperp = up->vdim == 1 ? 0.0 : val[3];
    double m1 = dens*upar, m2par = dens*(upar*upar+tpar);
    double m2perp = 2.0*dens*tperp, moments[4] = {0.0};
    switch (up->moment) {
      case GKYL_F_MOMENT_M0: moments[0] = dens; break;
      case GKYL_F_MOMENT_M1: moments[0] = m1; break;
      case GKYL_F_MOMENT_M2: moments[0] = m2par+m2perp; break;
      case GKYL_F_MOMENT_M2PAR: moments[0] = m2par; break;
      case GKYL_F_MOMENT_M2PERP: moments[0] = m2perp; break;
      case GKYL_F_MOMENT_M3PAR: moments[0] = m1*(upar*upar+3.0*tpar); break;
      case GKYL_F_MOMENT_M3PERP: moments[0] = 2.0*m1*tperp; break;
      case GKYL_F_MOMENT_MAXWELLIAN:
        moments[0] = dens; moments[1] = upar;
        moments[2] = up->vdim == 1 ? tpar : (tpar+2.0*tperp)/3.0;
        break;
      case GKYL_F_MOMENT_BIMAXWELLIAN:
        moments[0] = dens; moments[1] = upar;
        moments[2] = tpar; moments[3] = tperp;
        break;
      case GKYL_F_MOMENT_M0M1M2:
        moments[0] = dens; moments[1] = m1; moments[2] = m2par+m2perp;
        break;
      case GKYL_F_MOMENT_M0M1M2PARM2PERP:
        moments[0] = dens; moments[1] = m1;
        moments[2] = m2par; moments[3] = m2perp;
        break;
      case GKYL_F_MOMENT_HAMILTONIAN:
        moments[0] = dens; moments[1] = up->mass*m1;
        moments[2] = 0.5*up->mass*(m2par+m2perp)+up->charge*potential*dens;
        break;
      default: break; // Constructor rejects unsupported moments.
    }
    for (int c = 0; c < up->num_mom; ++c)
      for (int k = 0; k < nout; ++k)
        out[c*nout+k] += b[nb]*moments[c]*(up->integrated ? up->cell_factor : b[k]);
  }
}

#ifdef GKYL_HAVE_CUDA
void gkyl_gk_fluid_moments_advance_cu(const struct gkyl_gk_fluid_moments *up,
  const struct gkyl_range *range, const struct gkyl_array *state,
  const struct gkyl_array *phi, struct gkyl_array *out);
#endif
`,
"gyrokinetic/zero/gk_fluid_moments.c":`#include <assert.h>
#include <gkyl_alloc.h>
#include <gkyl_gauss_quad_data.h>
#include <gkyl_gk_fluid_moments_priv.h>

struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_new(const struct gkyl_basis *basis,
  const struct gkyl_rect_grid *grid, int vdim, double mass, double charge,
  enum gkyl_distribution_moments moment, bool integrated, bool use_gpu)
{
  assert(vdim == 1 || vdim == 2);
  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);
  *up = (struct gkyl_gk_fluid_moments) {
    .num_basis = basis->num_basis, .vdim = vdim, .mass = mass, .charge = charge,
    .moment = moment, .integrated = integrated, .use_gpu = use_gpu, .cell_factor = 1.0
  };
  switch (moment) {
    case GKYL_F_MOMENT_M0: case GKYL_F_MOMENT_M1: case GKYL_F_MOMENT_M2:
